CASE WHEN length(regexp_extract(_udf_param_0, '(?iu)is seeking () for ([^.]+)', 2)) > 2 THEN regexp_extract(_udf_param_0, '(?iu)is seeking () for ([^.]+)', 2) WHEN length(regexp_extract(_udf_param_0, '(?iu)admitted to the hospital for ([^.]+)', 1)) > 2 THEN regexp_extract(_udf_param_0, '(?iu)admitted to the hospital for ([^.]+)', 1) WHEN _udf_param_1 <> '' AND _udf_param_1 <> 'Other' AND _udf_param_2 <> '' AND _udf_param_2 <> 'Other' THEN concat(_udf_param_1, _udf_param_2) END
